"""Login sessions.

Refresh tokens rotate on every use: each refresh consumes the presented
token and mints its replacement in the same family. If a token is presented
a second time -- which only happens when a copy of an already-rotated token
is replayed, e.g. after theft -- the whole family is revoked, not just the
one token. Without that check, a stolen token would stay valid right
alongside the legitimate rotated one and nothing would ever notice the
theft.
"""

import secrets
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone

ACCESS_TOKEN_MINUTES = 15
REFRESH_TOKEN_DAYS = 90


@dataclass
class _Token:
    family_id: str
    issued_at: datetime
    status: str  # "active", "rotated", or "revoked"


_TOKENS: dict[str, _Token] = {}
_FAMILIES: dict[str, set[str]] = {}


def _now(now: datetime | None) -> datetime:
    return now or datetime.now(timezone.utc)


def _mint(family_id: str, moment: datetime) -> str:
    token = secrets.token_urlsafe(32)
    _TOKENS[token] = _Token(family_id=family_id, issued_at=moment, status="active")
    _FAMILIES.setdefault(family_id, set()).add(token)
    return token


def issue_refresh_token(now: datetime | None = None) -> str:
    """Start a new session and return its first refresh token."""
    moment = _now(now)
    family_id = secrets.token_urlsafe(16)
    return _mint(family_id, moment)


def refresh_expires_at(issued_at: datetime) -> datetime:
    return issued_at + timedelta(days=REFRESH_TOKEN_DAYS)


def is_refresh_valid(token: str, now: datetime | None = None) -> bool:
    record = _TOKENS.get(token)
    if record is None or record.status != "active":
        return False
    return _now(now) < refresh_expires_at(record.issued_at)


def rotate_refresh_token(token: str, now: datetime | None = None) -> str | None:
    """Consume `token` and return its replacement, or None if it can't rotate."""
    moment = _now(now)
    record = _TOKENS.get(token)
    if record is None:
        return None
    if record.status != "active":
        revoke_family(record.family_id)
        return None
    if moment >= refresh_expires_at(record.issued_at):
        record.status = "revoked"
        return None

    record.status = "rotated"
    return _mint(record.family_id, moment)


def revoke(token: str) -> None:
    """Revoke the session `token` belongs to, e.g. on logout."""
    record = _TOKENS.get(token)
    if record is not None:
        revoke_family(record.family_id)


def revoke_family(family_id: str) -> None:
    for member in _FAMILIES.get(family_id, ()):
        _TOKENS[member].status = "revoked"
